function mergeSort(a: number[]): number[] {
  if (a.length <= 1) return a; // base case
  const mid = Math.floor(a.length / 2);
  const left = mergeSort(a.slice(0, mid));
  const right = mergeSort(a.slice(mid));
  const out: number[] = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    out.push(left[i] <= right[j] ? left[i++] : right[j++]);
  }
  return [...out, ...left.slice(i), ...right.slice(j)];
}

function firstAtOrAfter(times: number[], target: number) {
  let lo = 0;
  let hi = times.length; // exclusive: one past the end
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (times[mid] < target) lo = mid + 1; // answer is right
    else hi = mid;                          // mid might be it
  }
  return lo; // times.length means: no match
}
